const sources = [
  { node: 'Fetch Reuters', name: 'Reuters' },
  { node: 'Fetch BBC', name: 'BBC News' },
  { node: 'Fetch Al Jazeera', name: 'Al Jazeera' },
  { node: 'Fetch Dawn', name: 'Dawn' },
];
const now = Date.now();
const out = [];
for (const s of sources) {
  let items = [];
  try { items = $(s.node).all(); } catch (e) { items = []; }
  for (const it of items) {
    const j = (it && it.json) ? it.json : {};
    const url = String(j.link || j.guid || '').trim();
    const headline = String(j.title || '').trim();
    // Exclude any article without a valid original URL or headline.
    if (!headline || !/^https?:\/\//i.test(url)) continue;
    const rawDate = j.isoDate || j.pubDate || '';
    let pubIso = '';
    if (rawDate) { const d = new Date(rawDate); if (!isNaN(d.getTime())) pubIso = d.toISOString(); }
    const ageHours = pubIso ? (now - new Date(pubIso).getTime()) / 3600000 : null;
    // Missing dates handled gracefully (kept); known dates older than 72h dropped.
    const isRecent = ageHours === null ? true : ageHours <= 72;
    let desc = String(j.contentSnippet || j.content || j.summary || j.description || '');
    desc = desc.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 1200);
    let img = '';
    if (j.enclosure && j.enclosure.url) img = String(j.enclosure.url);
    else if (j['media:content'] && j['media:content'].$ && j['media:content'].$.url) img = String(j['media:content'].$.url);
    const blob = (headline + ' ' + desc).toLowerCase();
    const isPromotional = /(advertisement|sponsored|promo code|shop now|buy now|discount code|use code|subscribe now|newsletter sign-?up)/.test(blob);
    const pubDate = pubIso ? new Date(pubIso).toUTCString() : 'Unknown';
    out.push({ json: { headline, description: desc, url, source: s.name, pubDate, pubDateIso: pubIso, imageUrl: img, hasUrl: true, isRecent, isPromotional, ageHours } });
  }
}
out.sort((a, b) => {
  const aa = a.json.ageHours === null ? Number.MAX_SAFE_INTEGER : a.json.ageHours;
  const bb = b.json.ageHours === null ? Number.MAX_SAFE_INTEGER : b.json.ageHours;
  return aa - bb;
});
if (out.length === 0) {
  // Sentinel item keeps the chain flowing (well-formed, filtered out downstream).
  return [{ json: { headline: '', description: '', url: '', source: '', pubDate: 'Unknown', pubDateIso: '', imageUrl: '', hasUrl: false, isRecent: false, isPromotional: false, ageHours: null } }];
}
return out;

const rows = $input.all().filter(i => i.json && i.json.headline && i.json.url);
const articles = rows.map((it, idx) => ({
  index: idx,
  headline: it.json.headline,
  description: it.json.description || '',
  source: it.json.source || '',
  pubDate: it.json.pubDate || 'Unknown',
  url: it.json.url,
  imageUrl: it.json.imageUrl || '',
}));
return [{ json: { articles, count: articles.length } }];

const LF = String.fromCharCode(10);
const ai = $input.first().json || {};
const summaries = (ai.output && ai.output.summaries) || ai.summaries || [];
const articles = ($('Prepare For AI').first().json.articles) || [];
const CATS = ['Technology & AI', 'Science', 'Business & Economy', 'World News', 'Pakistan News'];
const byIndex = {};
for (const s of summaries) { byIndex[s.index] = s; }
function esc(str){return String(str==null?'':str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
const merged = articles.map(a => {
  const s = byIndex[a.index] || {};
  let cat = s.category; if (!CATS.includes(cat)) cat = 'World News';
  const summary = (s.summary && String(s.summary).trim()) || a.description || 'Summary unavailable.';
  const sig = (typeof s.significance === 'number') ? s.significance : 0;
  const keyPoints = Array.isArray(s.key_points) ? s.key_points.filter(k => k != null && String(k).trim()).map(k => String(k).trim()) : [];
  const vocabulary = Array.isArray(s.vocabulary) ? s.vocabulary.filter(v => v && v.word) : [];
  return { headline: a.headline, summary, keyPoints, vocabulary, source: a.source, pubDate: a.pubDate, url: a.url, imageUrl: a.imageUrl, category: cat, significance: sig };
});
const dateStr = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
// ---- Markdown ----
const md = [];
md.push('# DAILY NEWS BRIEFING');
md.push('');
md.push('**Date:** ' + dateStr);
for (const cat of CATS) {
  const list = merged.filter(m => m.category === cat);
  md.push(''); md.push('## ' + cat);
  if (!list.length) { md.push(''); md.push('_No stories in this category today._'); continue; }
  for (const m of list) {
    md.push(''); md.push('### ' + m.headline);
    md.push(''); md.push('**Summary:**'); md.push(m.summary);
    if (m.keyPoints.length) { md.push(''); md.push('**Key Points:**'); m.keyPoints.forEach(k => md.push('- ' + k)); }
    if (m.vocabulary.length) { md.push(''); md.push('**Vocabulary:**'); m.vocabulary.forEach(v => md.push('- **' + v.word + '**: ' + (v.meaning || '') + ' _Example:_ ' + (v.example || ''))); }
    md.push(''); md.push('**Source:** ' + m.source);
    md.push('**Published:** ' + m.pubDate);
    md.push('**Original Article:** ' + m.url);
    md.push(''); md.push('---');
  }
}
const top = merged.slice().sort((a, b) => b.significance - a.significance).slice(0, 5);
md.push(''); md.push('## Top Stories');
if (!top.length) { md.push(''); md.push('_None._'); }
top.forEach((m, i) => { md.push((i + 1) + '. ' + m.headline + ' (' + m.source + ') — ' + m.url); });
const briefing_markdown = md.join(LF);
// ---- HTML ----
const h = [];
h.push('<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;margin:0 auto;color:#222;line-height:1.5">');
h.push('<h1 style="border-bottom:2px solid #444;padding-bottom:6px">Daily News Briefing</h1>');
h.push('<p><strong>Date:</strong> ' + esc(dateStr) + '</p>');
for (const cat of CATS) {
  const list = merged.filter(m => m.category === cat);
  h.push('<h2 style="margin-top:28px;color:#1a1a1a">' + esc(cat) + '</h2>');
  if (!list.length) { h.push('<p style="color:#888"><em>No stories in this category today.</em></p>'); continue; }
  for (const m of list) {
    h.push('<div style="margin:0 0 22px 0;padding-bottom:14px;border-bottom:1px solid #eee">');
    h.push('<h3 style="margin:0 0 6px 0">' + esc(m.headline) + '</h3>');
    if (m.imageUrl) h.push('<p><img src="' + esc(m.imageUrl) + '" alt="" style="max-width:100%;height:auto;border-radius:6px"/></p>');
    h.push('<p><strong>Summary:</strong><br/>' + esc(m.summary) + '</p>');
    if (m.keyPoints.length) { h.push('<p style="margin-bottom:4px"><strong>Key Points:</strong></p><ul style="margin-top:0">' + m.keyPoints.map(k => '<li>' + esc(k) + '</li>').join('') + '</ul>'); }
    if (m.vocabulary.length) { h.push('<p style="margin-bottom:4px"><strong>Vocabulary:</strong></p><ul style="margin-top:0">' + m.vocabulary.map(v => '<li><strong>' + esc(v.word) + '</strong>: ' + esc(v.meaning) + '<br/><em style="color:#555">Example: ' + esc(v.example) + '</em></li>').join('') + '</ul>'); }
    h.push('<p style="font-size:13px;color:#555"><strong>Source:</strong> ' + esc(m.source) + '<br/>');
    h.push('<strong>Published:</strong> ' + esc(m.pubDate) + '<br/>');
    h.push('<strong>Original Article:</strong> <a href="' + esc(m.url) + '">' + esc(m.url) + '</a></p>');
    h.push('</div>');
  }
}
h.push('<h2 style="margin-top:28px">Top Stories</h2>');
if (!top.length) { h.push('<p><em>None.</em></p>'); } else {
  h.push('<ol>');
  for (const m of top) { h.push('<li><a href="' + esc(m.url) + '">' + esc(m.headline) + '</a> <span style="color:#777">(' + esc(m.source) + ')</span></li>'); }
  h.push('</ol>');
}
h.push('</div>');
const briefing_html = h.join(LF);
return [{ json: { subject: 'Daily News Briefing \u2014 ' + dateStr, dateStr, count: merged.length, briefing_markdown, briefing_html } }];
